"use client";

import { useCallback, useEffect, useMemo, useState } from "react";

// ─── Types ────────────────────────────────────────────────────────────────────
type Role = "責任者" | "キッチン" | "ホール";

interface Staff {
  id: string;
  name: string;
  role: Role;
}

interface Shift {
  id: string;
  staffId: string;
  date: string; // YYYY-MM-DD
  startTime: string; // HH:MM
  endTime: string; // HH:MM
  breakMinutes: number;
}

// ─── Helpers ──────────────────────────────────────────────────────────────────
function timeToMinutes(t: string): number {
  const [h, m] = t.split(":").map(Number);
  return h * 60 + m;
}

function minutesToTime(m: number): string {
  const h = Math.floor(m / 60);
  const mm = m % 60;
  return `${String(h).padStart(2, "0")}:${String(mm).padStart(2, "0")}`;
}

function getWeekDates(ref: Date = new Date()): string[] {
  const d = new Date(ref);
  d.setDate(d.getDate() - d.getDay());
  const dates: string[] = [];
  for (let i = 0; i < 7; i++) {
    const day = new Date(d);
    day.setDate(d.getDate() + i);
    const y = day.getFullYear();
    const mo = String(day.getMonth() + 1).padStart(2, "0");
    const da = String(day.getDate()).padStart(2, "0");
    dates.push(`${y}-${mo}-${da}`);
  }
  return dates;
}

function shiftActualMinutes(s: Shift): number {
  return timeToMinutes(s.endTime) - timeToMinutes(s.startTime) - s.breakMinutes;
}

function formatHours(mins: number): string {
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return m === 0 ? `${h}時間` : `${h}時間${m}分`;
}

function is30MinGranularity(time: string): boolean {
  const m = /^([01]\d|2[0-3]):([05]0)$/.test(time);
  return m;
}

// ─── Main Component ───────────────────────────────────────────────────────────
export default function Page() {
  const [staff, setStaff] = useState<Staff[]>([]);
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  // Filters
  const [filterDate, setFilterDate] = useState<string>("");
  const [filterStaff, setFilterStaff] = useState<string>("");
  const [filterRole, setFilterRole] = useState<string>("");

  // Staff form
  const [staffName, setStaffName] = useState("");
  const [staffRole, setStaffRole] = useState<Role>("ホール");
  const [editingStaffId, setEditingStaffId] = useState<string | null>(null);
  const [staffFormError, setStaffFormError] = useState<string | null>(null);

  // Shift form
  const [shiftStaffId, setShiftStaffId] = useState("");
  const [shiftDate, setShiftDate] = useState("");
  const [shiftStart, setShiftStart] = useState("09:00");
  const [shiftEnd, setShiftEnd] = useState("17:00");
  const [shiftBreak, setShiftBreak] = useState(0);
  const [editingShiftId, setEditingShiftId] = useState<string | null>(null);
  const [shiftFormError, setShiftFormError] = useState<string | null>(null);

  // Fetch data on mount
  useEffect(() => {
    async function load() {
      try {
        setLoading(true);
        setError(null);
        const [staffRes, shiftsRes] = await Promise.all([
          fetch("/api/staff"),
          fetch("/api/shifts"),
        ]);
        if (!staffRes.ok) throw new Error("スタッフの取得に失敗しました");
        if (!shiftsRes.ok) throw new Error("シフトの取得に失敗しました");
        const staffData: Staff[] = await staffRes.json();
        const shiftsData: Shift[] = await shiftsRes.json();
        setStaff(staffData);
        setShifts(shiftsData);
        setSuccessMsg("データを正常に読み込みました");
      } catch (e) {
        setError(e instanceof Error ? e.message : "データの取得に失敗しました");
      } finally {
        setLoading(false);
      }
    }
    load();
  }, []);

  // Week dates
  const weekDates = useMemo(() => getWeekDates(), []);

  // Filtered shifts
  const filteredShifts = useMemo(() => {
    return shifts.filter((s) => {
      if (filterDate && s.date !== filterDate) return false;
      if (filterStaff && s.staffId !== filterStaff) return false;
      if (filterRole) {
        const st = staff.find((x) => x.id === s.staffId);
        if (!st || st.role !== filterRole) return false;
      }
      return true;
    });
  }, [shifts, staff, filterDate, filterStaff, filterRole]);

  // Per-staff weekly actual hours
  const weeklyHours = useMemo(() => {
    const map = new Map<string, number>();
    staff.forEach((s) => map.set(s.id, 0));
    shifts.forEach((s) => {
      map.set(s.staffId, (map.get(s.staffId) || 0) + shiftActualMinutes(s));
    });
    return map;
  }, [staff, shifts]);

  // Per-day per-role headcount
  const headcount = useMemo(() => {
    const map = new Map<string, Map<Role, number>>();
    weekDates.forEach((d) => map.set(d, new Map<Role, number>()));
    filteredShifts.forEach((s) => {
      const st = staff.find((x) => x.id === s.staffId);
      if (st && map.has(s.date)) {
        const roleMap = map.get(s.date)!;
        roleMap.set(st.role, (roleMap.get(st.role) || 0) + 1);
      }
    });
    return map;
  }, [filteredShifts, staff, weekDates]);

  // ─── Staff CRUD ─────────────────────────────────────────────────────────────
  async function handleStaffSubmit(e: React.FormEvent) {
    e.preventDefault();
    setStaffFormError(null);
    setSuccessMsg(null);

    if (!staffName.trim()) {
      setStaffFormError("氏名を入力してください");
      return;
    }

    try {
      if (editingStaffId) {
        const res = await fetch(`/api/staff/${editingStaffId}`, {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ name: staffName.trim(), role: staffRole }),
        });
        if (!res.ok) {
          const err = await res.json();
          setStaffFormError(err.error || "更新に失敗しました");
          return;
        }
        setSuccessMsg("スタッフを更新しました");
      } else {
        const res = await fetch("/api/staff", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ name: staffName.trim(), role: staffRole }),
        });
        if (!res.ok) {
          const err = await res.json();
          setStaffFormError(err.error || "作成に失敗しました");
          return;
        }
        setSuccessMsg("スタッフを作成しました");
      }
      setStaffName("");
      setStaffRole("ホール");
      setEditingStaffId(null);
      // refresh
      const staffRes = await fetch("/api/staff");
      setStaff(await staffRes.json());
    } catch {
      setStaffFormError("サーバーへの接続に失敗しました");
    }
  }

  async function handleStaffDelete(id: string) {
    try {
      const res = await fetch(`/api/staff/${id}`, { method: "DELETE" });
      if (!res.ok) {
        const err = await res.json();
        setStaffFormError(err.error || "削除に失敗しました");
        return;
      }
      setSuccessMsg("スタッフを削除しました");
      const staffRes = await fetch("/api/staff");
      setStaff(await staffRes.json());
    } catch {
      setStaffFormError("削除に失敗しました");
    }
  }

  function editStaff(s: Staff) {
    setEditingStaffId(s.id);
    setStaffName(s.name);
    setStaffRole(s.role);
  }

  // ─── Shift CRUD ─────────────────────────────────────────────────────────────
  async function handleShiftSubmit(e: React.FormEvent) {
    e.preventDefault();
    setShiftFormError(null);
    setSuccessMsg(null);

    // Client-side validation
    if (!shiftStaffId) {
      setShiftFormError("スタッフを選択してください");
      return;
    }
    if (!shiftDate) {
      setShiftFormError("日付を入力してください");
      return;
    }
    if (!is30MinGranularity(shiftStart)) {
      setShiftFormError("開始時刻は30分単位で入力してください");
      return;
    }
    if (!is30MinGranularity(shiftEnd)) {
      setShiftFormError("終了時刻は30分単位で入力してください");
      return;
    }
    if (timeToMinutes(shiftEnd) <= timeToMinutes(shiftStart)) {
      setShiftFormError("終了時刻は開始時刻より後でなければなりません");
      return;
    }
    const workMin = timeToMinutes(shiftEnd) - timeToMinutes(shiftStart);
    if (shiftBreak >= workMin) {
      setShiftFormError("休憩時間は勤務時間より短くしてください");
      return;
    }

    try {
      if (editingShiftId) {
        const res = await fetch(`/api/shifts/${editingShiftId}`, {
          method: "PUT",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            staffId: shiftStaffId,
            date: shiftDate,
            startTime: shiftStart,
            endTime: shiftEnd,
            breakMinutes: shiftBreak,
          }),
        });
        if (!res.ok) {
          const err = await res.json();
          setShiftFormError(err.error || "更新に失敗しました");
          return;
        }
        setSuccessMsg("シフトを更新しました");
      } else {
        const res = await fetch("/api/shifts", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            staffId: shiftStaffId,
            date: shiftDate,
            startTime: shiftStart,
            endTime: shiftEnd,
            breakMinutes: shiftBreak,
          }),
        });
        if (!res.ok) {
          const err = await res.json();
          setShiftFormError(err.error || "作成に失敗しました");
          return;
        }
        setSuccessMsg("シフトを作成しました");
      }
      setEditingShiftId(null);
      setShiftStaffId("");
      setShiftDate("");
      setShiftStart("09:00");
      setShiftEnd("17:00");
      setShiftBreak(0);
      const shiftsRes = await fetch("/api/shifts");
      setShifts(await shiftsRes.json());
    } catch {
      setShiftFormError("サーバーへの接続に失敗しました");
    }
  }

  async function handleShiftDelete(id: string) {
    try {
      const res = await fetch(`/api/shifts/${id}`, { method: "DELETE" });
      if (!res.ok) {
        const err = await res.json();
        setShiftFormError(err.error || "削除に失敗しました");
        return;
      }
      setSuccessMsg("シフトを削除しました");
      const shiftsRes = await fetch("/api/shifts");
      setShifts(await shiftsRes.json());
    } catch {
      setShiftFormError("削除に失敗しました");
    }
  }

  function editShift(s: Shift) {
    setEditingShiftId(s.id);
    setShiftStaffId(s.staffId);
    setShiftDate(s.date);
    setShiftStart(s.startTime);
    setShiftEnd(s.endTime);
    setShiftBreak(s.breakMinutes);
  }

  // ─── data-anvil-state snapshot ──────────────────────────────────────────────
  const anvilState = JSON.stringify({
    staffCount: staff.length,
    shiftCount: shifts.length,
    filters: { filterDate, filterStaff, filterRole },
    validationErrors: { staffFormError, shiftFormError },
    weeklyHours: Object.fromEntries(
      Array.from(weeklyHours.entries()).map(([k, v]) => [
        k,
        { minutes: v, over40: v > 2400 },
      ]),
    ),
  });

  // ─── Render ─────────────────────────────────────────────────────────────────
  return (
    <div
      className="min-h-screen bg-slate-50 text-slate-800"
      data-anvil-state={anvilState}
    >
      {/* Header */}
      <header className="bg-white border-b border-slate-200 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 py-4">
          <h1 className="text-2xl font-bold text-slate-900">
            ☕ カフェ週間シフト編成
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            スタッフ管理・シフト配置・実働時間レポート
          </p>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 py-6 space-y-6">
        {/* Status messages */}
        {loading && (
          <div className="bg-blue-50 border border-blue-200 text-blue-700 px-4 py-3 rounded-lg">
            ⏳ データを読み込み中...
          </div>
        )}
        {!loading && error && (
          <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg">
            ❌ {error}
          </div>
        )}
        {!loading && successMsg && !error && (
          <div className="bg-green-50 border border-green-200 text-green-700 px-4 py-3 rounded-lg">
            ✅ {successMsg}
          </div>
        )}

        {/* Staff CRUD */}
        <section className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
          <h2 className="text-lg font-semibold mb-4">スタッフ管理</h2>
          <form
            onSubmit={handleStaffSubmit}
            className="grid grid-cols-1 sm:grid-cols-3 gap-3 mb-4"
          >
            <div>
              <label className="block text-sm font-medium mb-1">氏名</label>
              <input
                type="text"
                value={staffName}
                onChange={(e) => setStaffName(e.target.value)}
                placeholder="氏名を入力"
                className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-400 focus:border-blue-400 outline-none"
                data-anvil-action="input"
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">役割</label>
              <select
                value={staffRole}
                onChange={(e) => setStaffRole(e.target.value as Role)}
                className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-400 outline-none"
              >
                <option value="責任者">責任者</option>
                <option value="キッチン">キッチン</option>
                <option value="ホール">ホール</option>
              </select>
            </div>
            <div className="flex items-end gap-2">
              <button
                type="submit"
                data-anvil-action="primary"
                className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors"
              >
                {editingStaffId ? "更新する" : "追加する"}
              </button>
              {editingStaffId && (
                <button
                  type="button"
                  onClick={() => {
                    setEditingStaffId(null);
                    setStaffName("");
                    setStaffRole("ホール");
                  }}
                  className="text-slate-500 text-sm hover:text-slate-700"
                >
                  キャンセル
                </button>
              )}
            </div>
          </form>
          {staffFormError && (
            <p className="text-red-600 text-sm mb-2">⚠️ {staffFormError}</p>
          )}
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-slate-200">
                  <th className="text-left py-2 px-3">氏名</th>
                  <th className="text-left py-2 px-3">役割</th>
                  <th className="text-left py-2 px-3">週間実働</th>
                  <th className="text-right py-2 px-3">操作</th>
                </tr>
              </thead>
              <tbody>
                {staff.length === 0 && !loading ? (
                  <tr>
                    <td colSpan={4} className="text-center text-slate-400 py-4">
                      スタッフがいません。上記フォームから追加してください。
                    </td>
                  </tr>
                ) : (
                  staff.map((s) => {
                    const hrs = weeklyHours.get(s.id) || 0;
                    return (
                      <tr key={s.id} className="border-b border-slate-100">
                        <td className="py-2 px-3 font-medium">{s.name}</td>
                        <td className="py-2 px-3">
                          <span
                            className={`px-2 py-0.5 rounded-full text-xs font-medium ${
                              s.role === "責任者"
                                ? "bg-purple-100 text-purple-700"
                                : s.role === "キッチン"
                                ? "bg-orange-100 text-orange-700"
                                : "bg-green-100 text-green-700"
                            }`}
                          >
                            {s.role}
                          </span>
                        </td>
                        <td className="py-2 px-3">
                          {formatHours(hrs)}
                          {hrs > 2400 && (
                            <span className="ml-2 text-red-500 text-xs font-bold">
                              ⚠️ 40時間超過
                            </span>
                          )}
                        </td>
                        <td className="py-2 px-3 text-right">
                          <button
                            onClick={() => editStaff(s)}
                            className="text-blue-600 hover:text-blue-800 text-xs mr-2"
                          >
                            編集
                          </button>
                          <button
                            onClick={() => handleStaffDelete(s.id)}
                            className="text-red-500 hover:text-red-700 text-xs"
                          >
                            削除
                          </button>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </section>

        {/* Shift CRUD */}
        <section className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
          <h2 className="text-lg font-semibold mb-4">シフト管理</h2>
          <form
            onSubmit={handleShiftSubmit}
            className="grid grid-cols-1 sm:grid-cols-3 lg:grid-cols-5 gap-3 mb-4"
          >
            <div>
              <label className="block text-sm font-medium mb-1">スタッフ</label>
              <select
                value={shiftStaffId}
                onChange={(e) => setShiftStaffId(e.target.value)}
                className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-400 outline-none"
              >
                <option value="">選択</option>
                {staff.map((s) => (
                  <option key={s.id} value={s.id}>
                    {s.name}（{s.role}）
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">日付</label>
              <input
                type="date"
                value={shiftDate}
                onChange={(e) => setShiftDate(e.target.value)}
                className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-400 outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">開始時刻</label>
              <input
                type="time"
                value={shiftStart}
                step={1800}
                onChange={(e) => setShiftStart(e.target.value)}
                className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-400 outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">終了時刻</label>
              <input
                type="time"
                value={shiftEnd}
                step={1800}
                onChange={(e) => setShiftEnd(e.target.value)}
                className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-400 outline-none"
              />
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">
                休憩（分）
              </label>
              <input
                type="number"
                value={shiftBreak}
                min={0}
                onChange={(e) => setShiftBreak(Number(e.target.value))}
                className="w-full border border-slate-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-blue-400 outline-none"
              />
            </div>
            <div className="sm:col-span-3 lg:col-span-1 flex items-end gap-2">
              <button
                type="submit"
                data-anvil-action="primary"
                className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors"
              >
                {editingShiftId ? "シフト更新" : "シフト追加"}
              </button>
              {editingShiftId && (
                <button
                  type="button"
                  onClick={() => {
                    setEditingShiftId(null);
                    setShiftStaffId("");
                    setShiftDate("");
                    setShiftStart("09:00");
                    setShiftEnd("17:00");
                    setShiftBreak(0);
                  }}
                  className="text-slate-500 text-sm hover:text-slate-700"
                >
                  キャンセル
                </button>
              )}
            </div>
          </form>
          {shiftFormError && (
            <p className="text-red-600 text-sm mb-2">⚠️ {shiftFormError}</p>
          )}
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-slate-200">
                  <th className="text-left py-2 px-3">スタッフ</th>
                  <th className="text-left py-2 px-3">日付</th>
                  <th className="text-left py-2 px-3">開始</th>
                  <th className="text-left py-2 px-3">終了</th>
                  <th className="text-left py-2 px-3">休憩</th>
                  <th className="text-left py-2 px-3">実働</th>
                  <th className="text-right py-2 px-3">操作</th>
                </tr>
              </thead>
              <tbody>
                {filteredShifts.length === 0 && !loading ? (
                  <tr>
                    <td colSpan={7} className="text-center text-slate-400 py-4">
                      条件に合うシフトがありません。
                    </td>
                  </tr>
                ) : (
                  filteredShifts.map((s) => {
                    const st = staff.find((x) => x.id === s.staffId);
                    return (
                      <tr key={s.id} className="border-b border-slate-100">
                        <td className="py-2 px-3 font-medium">
                          {st ? st.name : "不明"}
                        </td>
                        <td className="py-2 px-3">{s.date}</td>
                        <td className="py-2 px-3">{s.startTime}</td>
                        <td className="py-2 px-3">{s.endTime}</td>
                        <td className="py-2 px-3">{s.breakMinutes}分</td>
                        <td className="py-2 px-3">
                          {formatHours(shiftActualMinutes(s))}
                        </td>
                        <td className="py-2 px-3 text-right">
                          <button
                            onClick={() => editShift(s)}
                            className="text-blue-600 hover:text-blue-800 text-xs mr-2"
                          >
                            編集
                          </button>
                          <button
                            onClick={() => handleShiftDelete(s.id)}
                            className="text-red-500 hover:text-red-700 text-xs"
                          >
                            削除
                          </button>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
