import { NextRequest, NextResponse } from "next/server";
import { promises as fs } from "fs";
import path from "path";

const DATA_DIR = path.join(process.cwd(), "data");
const STAFF_FILE = path.join(DATA_DIR, "staff.json");

export type Role = "責任者" | "キッチン" | "ホール";

export interface Staff {
  id: string;
  name: string;
  role: Role;
}

async function readStaff(): Promise<Staff[]> {
  await fs.mkdir(DATA_DIR, { recursive: true });
  try {
    const content = await fs.readFile(STAFF_FILE, "utf-8");
    const data = JSON.parse(content);
    if (Array.isArray(data)) return data as Staff[];
    return [];
  } catch {
    return [];
  }
}

async function writeStaff(staff: Staff[]): Promise<void> {
  await fs.mkdir(DATA_DIR, { recursive: true });
  await fs.writeFile(STAFF_FILE, JSON.stringify(staff, null, 2), "utf-8");
}

function generateId(existing: Staff[]): string {
  const max = existing.reduce((acc, s) => {
    const n = parseInt(s.id, 10);
    return Number.isNaN(n) ? acc : Math.max(acc, n);
  }, 0);
  return String(max + 1);
}

const VALID_ROLES: Role[] = ["責任者", "キッチン", "ホール"];

// GET /api/staff
export async function GET() {
  try {
    const staff = await readStaff();
    return NextResponse.json(staff);
  } catch (err) {
    console.error("GET /api/staff failed:", err);
    return NextResponse.json({ error: "staff の読み込みに失敗しました" }, { status: 500 });
  }
}

// POST /api/staff  (create or upsert)
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const staff = await readStaff();

    const name = typeof body.name === "string" ? body.name.trim() : "";
    const role = body.role as Role;

    if (!name) {
      return NextResponse.json({ error: "氏名を入力してください" }, { status: 400 });
    }
    if (!VALID_ROLES.includes(role)) {
      return NextResponse.json({ error: "有効な役割を選択してください" }, { status: 400 });
    }

    if (body.id) {
      // update existing
      const idx = staff.findIndex((s) => s.id === body.id);
      if (idx === -1) {
        return NextResponse.json({ error: "スタッフが見つかりません" }, { status: 404 });
      }
      staff[idx] = { ...staff[idx], name, role };
      await writeStaff(staff);
      return NextResponse.json(staff[idx], { status: 200 });
    }

    // create new
    const newStaff: Staff = { id: generateId(staff), name, role };
    staff.push(newStaff);
    await writeStaff(staff);
    return NextResponse.json(newStaff, { status: 201 });
  } catch (err) {
    console.error("POST /api/staff failed:", err);
    return NextResponse.json({ error: "staff の保存に失敗しました" }, { status: 500 });
  }
