const SHIFTS_FILE = path.join(DATA_DIR, "shifts.json");
const STAFF_FILE = path.join(DATA_DIR, "staff.json");

export interface Shift {
  id: string;
  staffId: string;
  date: string;
  startTime: string;
  endTime: string;
  breakMinutes: number;
}

async function readShifts(): Promise<Shift[]> {
  await fs.mkdir(DATA_DIR, { recursive: true });
  try {
    const content = await fs.readFile(SHIFTS_FILE, "utf-8");
    const data = JSON.parse(content);
    if (Array.isArray(data)) return data as Shift[];
    return [];
  } catch {
    return [];
  }
}

async function writeShifts(shifts: Shift[]): Promise<void> {
  await fs.mkdir(DATA_DIR, { recursive: true });
  await fs.writeFile(SHIFTS_FILE, JSON.stringify(shifts, null, 2), "utf-8");
}

async function readStaffIds(): Promise<Set<string>> {
  try {
    const content = await fs.readFile(STAFF_FILE, "utf-8");
    const data = JSON.parse(content);
    if (Array.isArray(data)) return new Set(data.map((s: { id: string }) => s.id));
    return new Set();
  } catch {
    return new Set();
  }
}

function timeToMinutes(time: string): number {
  const [h, m] = time.split(":").map(Number);
  return h * 60 + m;
}

function isValidTime(time: string): boolean {
  const m = /^([01]\d|2[0-3]):([05]0)$/.exec(time);
  if (!m) return false;
  return true;
}

function isSameDay(a: string, b: string): boolean {
  return a === b;
}

// Check for overlap with adjacency allowed (end === start of next is OK)
function hasOverlap(shifts: Shift[], staffId: string, date: string, startTime: string, endTime: string, excludeId?: string): boolean {
  const newStart = timeToMinutes(startTime);
  const newEnd = timeToMinutes(endTime);
  const existing = shifts.filter(
    (s) => s.staffId === staffId && isSameDay(s.date, date) && s.id !== excludeId,
  );
  for (const s of existing) {
    const sStart = timeToMinutes(s.startTime);
    const sEnd = timeToMinutes(s.endTime);
    // Overlap if new.start < existing.end AND new.end > existing.start
    // Adjacency (new.start === sEnd or new.end === sStart) is allowed
    if (newStart < sEnd && newEnd > sStart) {
      return true;
    }
  }
  return false;
}

function generateId(existing: Shift[]): string {
  const max = existing.reduce((acc, s) => {
    const n = parseInt(s.id, 10);
    return Number.isNaN(n) ? acc : Math.max(acc, n);
  }, 0);
  return String(max + 1);
}

// GET /api/shifts
export async function GET() {
  try {
    const shifts = await readShifts();
    return NextResponse.json(shifts);
  } catch (err) {
    console.error("GET /api/shifts failed:", err);
    return NextResponse.json({ error: "shifts の読み込みに失敗しました" }, { status: 500 });
  }
}

// POST /api/shifts
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const shifts = await readShifts();

    const staffId = String(body.staffId || "");
    const date = String(body.date || "");
    const startTime = String(body.startTime || "");
    const endTime = String(body.endTime || "");
    const breakMinutes = Number(body.breakMinutes ?? 0);

    // Validation
    if (!staffId) return NextResponse.json({ error: "スタッフを選択してください" }, { status: 400 });
    if (!date) return NextResponse.json({ error: "日付を選択してください" }, { status: 400 });
    if (!isValidTime(startTime)) return NextResponse.json({ error: "開始時刻は 30 分単位で入力してください (HH:00 / HH:30)" }, { status: 400 });
    if (!isValidTime(endTime)) return NextResponse.json({ error: "終了時刻は 30 分単位で入力してください (HH:00 / HH:30)" }, { status: 400 });
    if (breakMinutes < 0 || breakMinutes % 30 !== 0) {
      return NextResponse.json({ error: "休憩分数は 0 または 30 の倍数にしてください" }, { status: 400 });
    }

    const startMin = timeToMinutes(startTime);
    const endMin = timeToMinutes(endTime);
    if (endMin <= startMin) {
      return NextResponse.json({ error: "終了時刻は開始時刻より後にしてください" }, { status: 400 });
    }

    const workMinutes = endMin - startMin;
    if (breakMinutes >= workMinutes) {
      return NextResponse.json({ error: "休憩時間は勤務時間未満にしてください" }, { status: 400 });
    }

    // Check staff exists
    const staffIds = await readStaffIds();
    if (!staffIds.has(staffId)) {
      return NextResponse.json({ error: "スタッフが見つかりません" }, { status: 404 });
    }

    // Overlap check
    if (hasOverlap(shifts, staffId, date, startTime, endTime, body.id ? String(body.id) : undefined)) {
      return NextResponse.json({ error: "同じスタッフの時間帯が重複しています" }, { status: 409 });
    }

    if (body.id) {
      // update
      const idx = shifts.findIndex((s) => s.id === body.id);
      if (idx === -1) {
        return NextResponse.json({ error: "シフトが見つかりません" }, { status: 404 });
      }
      shifts[idx] = { ...shifts[idx], staffId, date, startTime, endTime, breakMinutes };
      await writeShifts(shifts);
      return NextResponse.json(shifts[idx], { status: 200 });
    }

    const newShift: Shift = { id: generateId(shifts), staffId, date, startTime, endTime, breakMinutes };
    shifts.push(newShift);
    await writeShifts(shifts);
    return NextResponse.json(newShift, { status: 201 });
  } catch (err) {
    console.error("POST /api/shifts failed:", err);
    return NextResponse.json({ error: "shift の保存に失敗しました" }, { status: 500 });
  }
}

