    if (!isValidTime(startTime)) return NextResponse.json({ error: "開始時刻は 30 分単位で入力してください" }, { status: 400 });
    if (!isValidTime(endTime)) return NextResponse.json({ error: "終了時刻は 30 分単位で入力してください" }, { status: 400 });
    if (breakMinutes < 0 || breakMinutes % 30 !== 0) {
      return NextResponse.json({ error: "休憩分数は 0 または 30 の倍数にしてください" }, { status: 400 });
    }

    const startMin = timeToMinutes(startTime);
