    const startMin = timeToMinutes(startTime);
    const endMin = timeToMinutes(endTime);
    if (endMin <= startMin) {
      return NextResponse.json({ error: "終了時刻は開始時刻より後にしてください" }, { status: 400 });
    }

    // Validate break < work hours
    const workMinutes = endMin - startMin;
    if (breakMinutes < 0 || breakMinutes >= workMinutes) {
      return NextResponse.json({ error: "休憩分数は勤務時間より短くしてください" }, { status: 400 });
    }

    // Validate no overlap
    if (hasOverlap(shifts, staffId, date, startTime, endTime, id)) {
      return NextResponse.json({ error: "このスタッフの時間帯が重複しています" }, { status: 400 });
    }

    shifts[idx] = { ...shifts[idx], staffId, date, startTime, endTime, breakMinutes };
    await writeShifts(shifts);
    return NextResponse.json(shifts[idx]);
  } catch (err) {
    console.error("PUT /api/shifts/[id] failed:", err);
    return NextResponse.json({ error: "シフトの更新に失敗しました" }, { status: 500 });
  }
}

// DELETE /api/shifts/[id]
export async function DELETE(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    const { id } = params;
    const shifts = await readShifts();
    const idx = shifts.findIndex((s) => s.id === id);
    if (idx === -1) {
      return NextResponse.json({ error: "シフトが見つかりません" }, { status: 404 });
    }

    shifts.splice(idx, 1);
    await writeShifts(shifts);
    return NextResponse.json({ success: true });
  } catch (err) {
    console.error("DELETE /api/shifts/[id] failed:", err);
    return NextResponse.json({ error: "シフトの削除に失敗しました" }, { status: 500 });
  }
}
